SELECT e.id AS expenseId, e.period_id AS periodId, p.title AS periodTitle, e.item_id AS itemId, i.name AS itemName, e.title, e.amount, e.expense_date AS expenseDate, u.real_name AS handlerName, e.remark FROM budget_expense e LEFT JOIN budget_period p ON e.period_id = p.id LEFT JOIN budget_item i ON e.item_id = i.id LEFT JOIN sys_user u ON e.handler_id = u.id WHERE 1 = 1 AND e.deleted = 0
AND e.period_id = #{periodId}
AND e.item_id = #{itemId}
AND e.title LIKE CONCAT('%', #{keyword}, '%')
AND e.expense_date >= #{beginDate}
AND e.expense_date <= #{endDate}
ORDER BY e.expense_date DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM budget_expense e
LEFT JOIN budget_period p ON e.period_id = p.id
LEFT JOIN budget_item i ON e.item_id = i.id
WHERE 1 = 1
  AND e.deleted = 0

    AND e.period_id = #{periodId}


    AND e.item_id = #{itemId}


    AND e.title LIKE CONCAT('%', #{keyword}, '%')


    AND e.expense_date >= #{beginDate}


    AND e.expense_date <= #{endDate}
